INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 15, 'theory', 'Квиз: HTML: формы и доступность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 0, 'Что произойдёт с полем формы, у которого нет атрибута name?', '["Оно уйдёт в запрос с пустым именем","Браузер возьмёт имя из атрибута id","Оно не попадёт в запрос, сколько бы человек в него ни написал","Форма не отправится вообще"]', 2, 'В запрос идут пары «имя=значение», которые браузер собирает по name; id нужен для связей, стилей и скриптов и в запрос не попадает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 1, 'Зачем нужен label, связанный с полем через for или обёрткой?', '["Чтобы значение поля попало в запрос","Клик по подписи ставит курсор в поле, а скринридер читает название при входе в поле","Чтобы поле стало обязательным","Чтобы браузер подставлял сохранённый пароль"]', 1, 'Подпись увеличивает цель для нажатия и даёт вспомогательным технологиям название поля. Placeholder её не заменяет: он исчезает при вводе и не всегда озвучивается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 2, 'Что сделает кнопка button без атрибута type внутри формы?', '["Ничего, пока не добавлен скрипт","Сбросит поля к начальным значениям","Поведёт себя как type=\"button\"","Отправит форму, как type=\"submit\""]', 3, 'По умолчанию тип кнопки — submit, поэтому любую вспомогательную кнопку внутри формы (показать пароль, добавить строку) помечают type="button".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 3, 'Чем readonly отличается от disabled?', '["Readonly-поле получает фокус и уходит в запрос, но не редактируется; disabled-поле не получает фокус и в запрос не уходит","Они ничем не отличаются","Disabled-поле уходит в запрос, а readonly — нет","Readonly скрывает поле, а disabled показывает серым"]', 0, 'Disabled выключает поле полностью, readonly оставляет его видимым, доступным для выделения и отправляемым, только править значение нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 4, 'Как правильно сообщить об ошибке в поле формы?', '["Подсветить поле красной рамкой","Показать всплывающее окно alert и очистить поле","Написать текст рядом с полем, связать его через aria-describedby и поставить aria-invalid=\"true\"","Заблокировать кнопку отправки без пояснений"]', 2, 'Цвет не различают часть людей и не слышит скринридер. Текст говорит, что случилось и как исправить, а связь через describedby и aria-invalid делает ошибку доступной.');
